import{_ as o,o as u,c as q,ag as a}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"金刚经5分-离相","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经5分-离相.md","filePath":"60-原文段落/金刚经5分-离相.md","lastUpdated":1778155802000}'),e={name:"60-原文段落/金刚经5分-离相.md"};function p(r,t,s,n,_,c){return u(),q("div",null,[...t[0]||(t[0]=[a('<h1 id="金刚经5分-离相" tabindex="-1">金刚经5分-离相 <a class="header-anchor" href="#金刚经5分-离相" aria-label="Permalink to &quot;金刚经5分-离相&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/5了空居士讲《金刚经》-第五分如理实见分20160930">5了空居士讲《金刚经》-第五分如理实见分20160930</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>凡所有相，皆是虚妄。若见诸相非相，即见如来。</strong></p><p>就是佛祖对须菩提说：&quot;凡所有相，皆是虚妄&quot;。就是一切的现象，都不是绝对真实，这里的&quot;虚妄&quot;就是虚而不实，妄而不真，&quot;虚妄&quot;的意思就是不实不真的，一些现象不一定绝对是真的啦，这&quot;凡所有相，皆是虚妄&quot;，一切现象，都不一定是真实的啊。我以前也说过，&quot;虚妄&quot;也是不永恒的意思，不永恒的意思其实就是说它会变化的。会变化，其实也是告诉我们不够真实。</p><p>&quot;若见诸相非相，即见如来&quot;，这里关键词就是&quot;诸相非相&quot;。&quot;若见诸相非相&quot;就是：你不要被现象所迷惑，产生执著。如果你对看到什么东西，就认为你看到的就是真实的，产生了这种执著，那么你这个就没有&quot;见如来&quot;。如果你能够&quot;若见诸相非相，即见如来&quot;，就是说，如果你在一切环境一切现象面前，你都不会产生执着，也就是说，你的心永远清净的，你能够在任何场合都保持以清净的心去面对一切，这个时候你就&quot;见如来&quot;了。</p><p><strong>离相即客观</strong></p><p>我告诉你，就是以最清净最客观的心去看待一切，包括是看待自己，这就是&quot;离相&quot;。&quot;离相&quot;，你们不要以为这个相怎么&quot;离&quot;，&quot;离相&quot;反过来就是着相，着相就是被现象所迷惑，打个比方一个人骂你，你就生气，为什么？因为你认为他在骂你。如果你是一个旁观者，人家在骂另外一个人，然后说，你以最客观的心来评论一下，那么你这个时候就是&quot;离相&quot;。我们读历史，往往就能够心平气和，如果这件事情发生在自己身上，哇，那你就情绪波动了是不是？所以这就是不会被现象所干扰，这就是&quot;离相&quot;。</p><p>我举个例子，司马光小时候跟几个小孩在花园里面玩，有个小孩爬在树上，不小心掉到一个很大很大的金鱼缸，掉到一个金鱼缸里面去。哇，司马光很聪明，他赶快抱起旁边一个石头将这个金鱼缸给砸烂，这一砸烂，水流出来，小孩就不会被淹死，这种做法让我来说，它就是&quot;离相&quot;。如果换做其他小孩子说，砸烂这个金鱼缸等一下会不会被大人骂？这个金鱼缸是我家的，很漂亮啊，砸烂了不就浪费了嘛？如果他多想几下，那小孩淹死了。这个时候他就是以最客观的心，&quot;救人要紧&quot;，赶快拿块石头将金鱼缸砸烂啊，水流出来就没事了，所以这个最清净的心，他就充满智慧，他就能够将事情看得详细周到。</p><p><strong>&quot;虚妄&quot;是最积极的</strong></p><p>&quot;凡所有相皆是虚妄&quot;这句话对我们现实人生有这样一种积极的指导意义：这是最积极的！就是说一切事物都是在发展变化，只要我们积极地去努力，未来会更加好。你说未来会更加好，它也是&quot;虚妄&quot;的，怎么办？没事，你就未来继续努力下去，那未来的未来那不就更好吗？这个&quot;虚妄&quot;就是它不稳定，它在变化，然后我们有良好的助缘，就是使它不断地往更好的方向变化嘛，所以让我来说是这是一个好消息，能够使我们正精进。</p><hr><p><strong>理智：修行的操作手柄</strong></p><p>你怎么才能永远平静地做事呢？你只要掌握一个要诀，当你不平静的时候，你问自己，我为什么要不平静，我这样的不平静正确吗？是不是啊？好像我们在忍无可忍的时候会挺身而出等等，关键就看你这个时候挺身而出是对的还是错的，对整个大局来说是好的还是坏的。</p><p>你看韩信胯下之辱，我相信他那个时候心里也不平静，但是他想一想：不平静有用吗？还是爬过去算了啊，也许他以不平静的心爬过去，也许他想通了。其实他的心虽然不平静，但是已经没有那么不平静了。保持平静的要诀就是保持理智地去看待一切。</p>',15)])])}const l=o(e,[["render",p]]);export{d as __pageData,l as default};
